add_action( 'woocommerce_email_after_order_table', 'perfectpixel_payment_method_in_emails', 15, 4 );

function perfectpixel_payment_method_in_emails( $order, $sent_to_admin, $plain_text, $email ) {
	$title = $order->get_payment_method_title();
	if ( '' === (string) $title ) {
		return;
	}
	if ( $plain_text ) {
		echo "\n" . esc_html( '{{email_payment_label}}' ) . ' ' . esc_html( $title ) . "\n";
	} else {
		echo '<p><strong>' . esc_html( '{{email_payment_label}}' ) . '</strong> ' . esc_html( $title ) . '</p>';
	}
}
